//package com.company;

import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    public static class Task {
        private static final int MOD = 998244353;

        private int add(int a, int b) {
            int sum = a + b;
            if (sum >= MOD) return sum - MOD;
            if (sum < 0) return sum + MOD;
            return sum;
        }

        private int multiply(int x, int y) {
            return (int) ((long) x * y % MOD);
        }

        private int multiply(int... values) {
            int product = 1;
            for (int v : values) {
                product = multiply(product, v);
            }
            return product;
        }

        private int[][] stirling;

        private void initializeStirling() {
            stirling = new int[5001][5001];
            for (int i = 0; i < 5001; i++) {
                stirling[i][0] = 0;
                stirling[0][i] = (i == 1) ? 1 : 0;
            }
            for (int i = 1; i < 5001; i++) {
                stirling[i][i] = 1;
            }
            for (int i = 2; i < 5001; i++) {
                for (int j = 1; j < i; j++) {
                    stirling[i][j] = add(multiply(stirling[i-1][j], i-1), stirling[i-1][j-1]);
                }
            }
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            initializeStirling();
            int n = sc.nextInt();
            int m = sc.nextInt();
            int k = sc.nextInt();

            int invM = BigInteger.valueOf(m).modInverse(BigInteger.valueOf(MOD)).intValue();

            int[] p = new int[5001];
            p[0] = 1;
            int remaining = n;
            int power = 1;

            for (int i = 1; i <= k; i++) {
                power = multiply(power, remaining, invM);
                remaining = add(remaining, MOD - 1);

                int temp = power;
                for (int j = i-1; j >= 1; j--) {
                    int contribution = multiply(stirling[i][j], p[j]);
                    if ((i - j) % 2 == 1) {
                        temp = add(temp, contribution);
                    } else {
                        temp = add(temp, MOD - contribution);
                    }
                }
                p[i] = temp;
            }

            pw.println(p[k]);
        }
    }

    private static long startTimestamp, endTimestamp;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

        Runtime rt = Runtime.getRuntime();
        long memBefore = rt.totalMemory() - rt.freeMemory();
        startTimestamp = System.currentTimeMillis();

        Task solver = new Task();
        solver.solve(sc, pw);

        endTimestamp = System.currentTimeMillis();
        long memAfter = rt.totalMemory() - rt.freeMemory();

        pw.close();
        System.err.println("Memory increased: " + (memAfter - memBefore) / 1000000);
        System.err.println("Time used: " + (endTimestamp - startTimestamp) + ".");
    }

    static class Scanner {
        private StringTokenizer tokens;
        private BufferedReader input;

        public Scanner(InputStream stream) {
            input = new BufferedReader(new InputStreamReader(stream));
        }

        public Scanner(FileReader file) throws FileNotFoundException {
            input = new BufferedReader(file);
        }

        public String next() throws IOException {
            while (tokens == null || !tokens.hasMoreElements()) {
                tokens = new StringTokenizer(input.readLine());
            }
            return tokens.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return input.readLine();
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public boolean ready() throws IOException {
            return input.ready();
        }
    }
}
